{
  "meetingType": "team_sync",
  "overview": null,
  "sections": [
    {
      "title": {
        "text": "Logistics and Site Preparation",
        "sources": [
          "R1",
          "R2",
          "R10",
          "R15"
        ]
      },
      "items": [
        {
          "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate and the lift is functional.",
          "sources": [
            "R1"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The entrance includes a bench by the coat hooks; the access inspection confirmed the route and doorway.",
          "sources": [
            "R10",
            "R15"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Artwork and Documentation",
        "sources": [
          "R0",
          "R6",
          "R7",
          "R8",
          "R9"
        ]
      },
      "items": [
        {
          "text": "The artwork courier will be booked by Thursday once the insurance certificate is approved.",
          "sources": [
            "R0"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "The artist descriptions vary in tone and should be preserved as such.",
          "sources": [
            "R6"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The printed catalogue will be limited to 100 copies with a QR link for additional readers due to budget constraints.",
          "sources": [
            "R8"
          ],
          "kind": "decision",
          "owner": null,
          "due": null
        },
        {
          "text": "The catalogue PDF and QR link are already functional and contain the same artist descriptions as the printed copies.",
          "sources": [
            "R9"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Visitor Experience and Promotion",
        "sources": [
          "R4",
          "R5",
          "R11",
          "R14",
          "R17"
        ]
      },
      "items": [
        {
          "text": "Omar offered to record a narrated audio tour; the offer remains unaccepted.",
          "sources": [
            "R4",
            "R16"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "Trial observations regarding visitor preferences and artist sentiments are noted as part of the exhibition understanding.",
          "sources": [
            "R5",
            "R11"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The actual floor plan should be used to discuss the layout with visitors.",
          "sources": [
            "R14"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        },
        {
          "text": "The preview results are distinct from the upcoming public opening.",
          "sources": [
            "R17"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    },
    {
      "title": {
        "text": "Internal Coordination",
        "sources": [
          "R3",
          "R12",
          "R18"
        ]
      },
      "items": [
        {
          "text": "Priya will send the existing floor plan to Lena by Thursday.",
          "sources": [
            "R18"
          ],
          "kind": "action",
          "owner": "Priya",
          "due": "Thursday"
        },
        {
          "text": "The commitment to replace the camera equipment list was withdrawn as the folder already contains the corrected list.",
          "sources": [
            "R12"
          ],
          "kind": "point",
          "owner": null,
          "due": null
        }
      ]
    }
  ],
  "recentWin": {
    "win": {
      "text": "The gallery inspection confirmed the loading door is wide enough for the largest crate and the lift worked.",
      "sources": [
